"""OpenAI Agents SDK integration — PREVIEW.

OpenAI's Agents SDK ships a tracing system based on the
``TracingProcessor`` protocol. Processors are registered globally via
``agents.add_trace_processor(processor)`` and receive lifecycle events
for traces and spans (agent runs, generations, tool calls, handoffs).

Status: PREVIEW.

What this module provides today:
- ``PRISMtraceTracingProcessor`` — implements the OpenAI Agents
  ``TracingProcessor`` protocol shape (start/end on traces and spans,
  shutdown, force_flush). On span end, it POSTs a single PRISMtrace
  trace to ``/api/traces`` with framework=openai_agents metadata so the
  run is detectable in Agent Runs.
- ``install(api_key, project_id, ...)`` convenience that registers the
  processor with the Agents SDK in one call.

What is NOT yet production-grade (the reason this is PREVIEW, not
Supported):
- Span hierarchy is flattened: we POST one trace per span instead of
  rebuilding the Agents SDK's nested span tree as PRISMtrace spans on
  one parent trace. This means handoff structure is visible only via
  session_id grouping, not as nested span rows.
  Agent-boundary spans are no longer forwarded at all: because they
  ENCLOSE the generations and tool calls under them, a flattened agent
  span made the run's summed step time count the same milliseconds
  twice. See ADR-0137.
- Streaming chunks are not aggregated; we capture the final response
  text on span end.
- Tool call results are captured as separate traces tagged
  ``tool_call`` rather than nested under the generation span.

These gaps are tracked for the next iteration. The current shape is
intentionally narrow so we ship a working integration we can hand to
a customer today, with a clear roadmap to deeper structural fidelity.

Usage:

    from agents import Agent, Runner
    from prismtrace import install_openai_agents

    install_openai_agents(api_key="pt-sk-...", project_id="<uuid>")

    # Every agent.run() / Runner.run() execution now flushes to PRISMtrace.
    agent = Agent(name="my-agent", instructions="...")
    result = await Runner.run(agent, "hello")
"""
from __future__ import annotations


import time
import threading
import uuid
from typing import Any, Optional

import httpx
from ._config import DEFAULT_HOST, resolve_host
from ._session import resolve_session


_FRAMEWORK_TAG = "openai-agents"
_DEFAULT_ENDPOINT = DEFAULT_HOST


class PRISMtraceTracingProcessor:
    """Implements OpenAI Agents SDK's TracingProcessor protocol.

    Methods follow the SDK's published interface:
        - on_trace_start(trace)
        - on_trace_end(trace)
        - on_span_start(span)
        - on_span_end(span)
        - shutdown()
        - force_flush()

    PREVIEW: each closed span is forwarded as a single PRISMtrace trace.
    We do NOT yet reconstruct the Agents-SDK span tree as a single
    PRISMtrace trajectory with nested spans — see module docstring.
    """

    def __init__(
        self,
        api_key: str,
        project_id: str,
        endpoint: Optional[str] = None,
        agent_name: str = f"{_FRAMEWORK_TAG}-agent",
        timeout: int = 10,
    ) -> None:
        self.api_key = api_key
        self.project_id = project_id
        self.endpoint = resolve_host(endpoint)
        self.agent_name = agent_name
        # Seconds per POST; the SDK fails open, so this bounds silent loss
        # against a slow backend (KAN-47). Same argument the voice tracer takes.
        self.timeout = timeout
        self._http = httpx.Client(
            headers={
                "X-PRISMtrace-Key": api_key,
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )
        # Session id per top-level Agents-SDK trace. Each Runner.run() is
        # one Agents-SDK "trace"; we map that 1:1 to one PRISMtrace
        # session_id so all spans within a run share a session and the
        # backend's trajectory assembler clusters them automatically.
        self._trace_sessions: dict[str, str] = {}
        # The Agents SDK hands span callbacks to whichever thread finished the
        # work, so the map above is written from more than one of them.
        self._lock = threading.Lock()
        self._closed = False

    # ------------------------------------------------------------------
    # TracingProcessor protocol
    # ------------------------------------------------------------------

    def on_trace_start(self, trace: Any) -> None:
        trace_id = self._trace_id(trace)
        if not trace_id:
            return
        with self._lock:
            if trace_id not in self._trace_sessions:
                # An ambient session, when one is open, beats the generated id:
                # it lets a caller group several Runner.run() calls into one
                # conversation instead of one session per run.
                self._trace_sessions[trace_id] = resolve_session(
                    None, str(uuid.uuid4())
                )

    def on_trace_end(self, trace: Any) -> None:
        trace_id = self._trace_id(trace)
        # Keep the session in the dict — late span_end events for this
        # trace may still arrive. Drop on shutdown instead.
        _ = trace_id

    def on_span_start(self, span: Any) -> None:
        # Nothing to post yet; PRISMtrace gets a single trace per span on end.
        return

    def on_span_end(self, span: Any) -> None:
        try:
            self._forward_span(span)
        except Exception as exc:
            # Tracing must never break the user's agent. Fail open.
            print(f"[prismtrace openai-agents] forward failed: {exc}")

    def shutdown(self) -> None:
        """TracingProcessor protocol name for :meth:`close`."""
        self.close()

    def close(self) -> None:
        """Release the HTTP connection pool. Idempotent."""
        if self._closed:
            return
        self._closed = True
        try:
            self._http.close()
        except Exception:
            pass
        with self._lock:
            self._trace_sessions.clear()

    def __enter__(self) -> "PRISMtraceTracingProcessor":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False

    def force_flush(self) -> None:
        # No internal buffer — each on_span_end POSTs synchronously.
        return

    # ------------------------------------------------------------------
    # Span → PRISMtrace trace mapping
    # ------------------------------------------------------------------

    #: Span kinds that ENCLOSE other spans rather than doing work themselves.
    #: An agent span's duration is the total of the generations and tool calls
    #: nested inside it, so forwarding it as a sibling trace of its own children
    #: charged the same milliseconds twice in the run's summed step time
    #: (ADR-0137). google_adk.py declines to emit agent-boundary traces for the
    #: same reason; this matches it. Both the SDK's own `type` value and the
    #: class-name fallback from _guess_kind are listed, because either can be
    #: what lands in span_kind.
    _ENCLOSING_SPAN_KINDS = frozenset({"agent", "AgentSpanData"})

    def _forward_span(self, span: Any) -> None:
        span_data = getattr(span, "span_data", None) or span
        span_kind = getattr(span_data, "type", None) or self._guess_kind(span_data)

        # The agent boundary is still reconstructible: every child trace carries
        # the same session_id, so the run groups exactly as before. What is gone
        # is a step whose duration was a second copy of its children's.
        if str(span_kind) in self._ENCLOSING_SPAN_KINDS:
            return

        trace_id_str = getattr(span, "trace_id", None)
        with self._lock:
            session_id = self._trace_sessions.get(str(trace_id_str))
        if not session_id:
            # A span with no on_trace_start we saw. Prefer the ambient session
            # over the raw Agents-SDK trace id so it still groups with its run.
            session_id = resolve_session(
                None, str(trace_id_str) or str(uuid.uuid4())
            )

        # Tag the model field so the server architecture extractor maps to
        # framework=openai_agents. The underlying model id is preserved.
        raw_model = getattr(span_data, "model", None) or self._guess_model(span_data) or "unknown"
        tagged_model = f"{_FRAMEWORK_TAG}:{span_kind}:{raw_model}" if span_kind else f"{_FRAMEWORK_TAG}:{raw_model}"

        latency_ms = self._duration_ms(span)
        input_messages = self._extract_input(span_data)
        output_message = self._extract_output(span_data)
        token_input, token_output = self._extract_tokens(span_data)

        payload = {
            "project_id": self.project_id,
            "model": tagged_model,
            "input_messages": input_messages,
            "output_message": output_message,
            "latency_ms": latency_ms,
            "token_count_input": token_input,
            "token_count_output": token_output,
            "session_id": session_id,
            "metadata": {
                "framework": "openai_agents",
                "agent_name": self.agent_name,
                "agent_id": self.agent_name,
                "source": "openai-agents-sdk",
                "session_id": session_id,
                "agents_span_kind": str(span_kind) if span_kind else None,
                "agents_trace_id": str(trace_id_str) if trace_id_str else None,
                "agents_span_id": str(getattr(span, "span_id", "")) or None,
            },
        }
        self._http.post(f"{self.endpoint}/api/traces", json=payload)

    # ------------------------------------------------------------------
    # Best-effort field extraction (Agents SDK span shapes vary)
    # ------------------------------------------------------------------

    @staticmethod
    def _trace_id(trace: Any) -> Optional[str]:
        tid = getattr(trace, "trace_id", None) or getattr(trace, "id", None)
        return str(tid) if tid else None

    @staticmethod
    def _duration_ms(span: Any) -> int:
        try:
            start = getattr(span, "started_at", None) or getattr(span, "start_time", None)
            end = getattr(span, "ended_at", None) or getattr(span, "end_time", None)
            if start is None or end is None:
                return 0
            if hasattr(end, "timestamp") and hasattr(start, "timestamp"):
                return int((end.timestamp() - start.timestamp()) * 1000)
            return int((float(end) - float(start)) * 1000)
        except Exception:
            return 0

    @staticmethod
    def _guess_kind(span_data: Any) -> Optional[str]:
        # SDK span_data subclasses include GenerationSpanData, FunctionSpanData,
        # AgentSpanData, HandoffSpanData. Use the class name as a hint.
        return type(span_data).__name__ if span_data is not None else None

    @staticmethod
    def _guess_model(span_data: Any) -> Optional[str]:
        for attr in ("model", "model_name"):
            v = getattr(span_data, attr, None)
            if v:
                return str(v)
        return None

    @staticmethod
    def _extract_input(span_data: Any) -> list:
        # GenerationSpanData exposes `input` as a list of messages.
        inp = getattr(span_data, "input", None)
        if isinstance(inp, list):
            out = []
            for m in inp:
                if isinstance(m, dict):
                    out.append({"role": str(m.get("role", "user")), "content": str(m.get("content", ""))[:16000]})
                else:
                    out.append({"role": "user", "content": str(m)[:16000]})
            return out
        # FunctionSpanData / AgentSpanData fall back to a single representation.
        if inp is not None:
            return [{"role": "user", "content": str(inp)[:16000]}]
        return []

    @staticmethod
    def _extract_output(span_data: Any) -> str:
        out = getattr(span_data, "output", None)
        if out is None:
            return ""
        if isinstance(out, list) and out:
            first = out[0]
            if isinstance(first, dict):
                return str(first.get("content", first))[:16000]
            return str(first)[:16000]
        return str(out)[:16000]

    @staticmethod
    def _extract_tokens(span_data: Any) -> tuple[int, int]:
        usage = getattr(span_data, "usage", None) or {}
        def _g(name: str) -> int:
            v = usage.get(name) if isinstance(usage, dict) else getattr(usage, name, None)
            try:
                return int(v or 0)
            except (TypeError, ValueError):
                return 0
        return _g("input_tokens") or _g("prompt_tokens"), _g("output_tokens") or _g("completion_tokens")


def install(
    api_key: str,
    project_id: str,
    endpoint: Optional[str] = None,
    agent_name: str = f"{_FRAMEWORK_TAG}-agent",
    timeout: int = 10,
) -> PRISMtraceTracingProcessor:
    """Register a PRISMtraceTracingProcessor with the OpenAI Agents SDK.

    Returns the processor instance so callers can introspect or remove it
    via the SDK's own deregistration API in a future SDK version.
    """
    try:
        from agents import tracing  # type: ignore[import-not-found]
    except ImportError as exc:
        raise ImportError(
            "openai-agents is required. Install with: pip install openai-agents"
        ) from exc

    processor = PRISMtraceTracingProcessor(
        api_key=api_key,
        project_id=project_id,
        endpoint=endpoint,
        agent_name=agent_name,
        timeout=timeout,
    )
    # Agents SDK exposes `add_trace_processor` at the tracing module level
    # in current versions. If the SDK has renamed it, raise with a clear
    # message rather than silently failing.
    if hasattr(tracing, "add_trace_processor"):
        tracing.add_trace_processor(processor)
    elif hasattr(tracing, "set_trace_processors"):
        tracing.set_trace_processors([processor])
    else:
        raise RuntimeError(
            "openai-agents tracing module exposes neither add_trace_processor "
            "nor set_trace_processors. Upgrade openai-agents or register the "
            "processor manually."
        )
    return processor
